import clsx from 'clsx';
import { Fragment } from 'react/jsx-runtime';
import { FormProvider, SubmitHandler, useForm } from 'react-hook-form';
import { AppParams } from '~/entities/super-app/model/types';
import { useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { AccountCheckRequest } from '~/entities/pin/api/dtos/types';
import { useAccountCheckMutation } from '~/entities/pin/api/use-account-check-mutation';
import { CBDCAxiosError } from '~/shared/@types/error';
import { VerificationType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import { createFormOptions } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';
import { TextInput } from '~/shared/ui/text-input/text-input';

type Inputs = {
  bankAccount: string;
  bankCode: string;
};

export const VerifyBankPage = () => {
  const { routerState: backState } = useGetRouterState<AppParams>();
  const { routerState: state } = useGetRouterState<AppParams>();
  const { openAlertDialog } = useAlertDialog();
  const { navigate } = useNavigate();

  const { bankName } = useComBankInfo(appConfig.BANK_CODE);

  const { mutateAsync: accountCheck } = useAccountCheckMutation();
  const form = useForm<Inputs>({
    mode: 'all',
    defaultValues: {
      bankAccount: state.acnutno || '',
      bankCode: appConfig.BANK_CODE,
    },
  });

  const { register, handleSubmit, watch } = form;
  const watchAllFields = watch();
  const isDisabled = !watchAllFields.bankAccount || !watchAllFields.bankCode;
  const formOptions = createFormOptions<Inputs>();
  const onSubmit: SubmitHandler<Inputs> = async (data) => {
    const param: AccountCheckRequest = {
      customerId: state.cstmrNo,
      acnutNo: data.bankAccount,
      koreanNm: state?.koreanNm,
    };
    try {
      const response = await accountCheck(param);
      if (response) {
        const retData: AppParams = { ...state };
        retData.acnutno = data.bankAccount;

        navigate(PATHS.signUp.termsAndConditions, { replace: true, state: { ...retData } });
      } else {
        openAlertDialog({ message: i18n.t('validation:accountInfoCheckError') });
      }
    } catch (error: unknown) {
      const axiosError = error as CBDCAxiosError;
      if (axiosError?.response?.data?.message) {
        openAlertDialog({ message: axiosError?.response?.data?.message });
      } else {
        openAlertDialog({ message: i18n.t('validation:accountInfoCheckError') });
      }
    }
  };

  useSetOnBack(() =>
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          onConfirmClick={() => {
            setTimeout(() => {
              if (state.verificationType === VerificationType.ReSetUser) {
                navigate(PATHS.account.myBankAccount, { replace: true });
              } else {
                navigate(PATHS.mobileVerification, { replace: true, state: { ...backState } });
              }
            }, 0);
          }}
          title={i18n.t('validation:returnToBeginning')}
          message={i18n.t('validation:authInfoResetWarning')}
          buttonLabel={[i18n.t('cancel'), i18n.t('goBack')]}
        />
      );
    }),
  );

  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <div className="sub-step">
          <span className="on">{i18n.t('step1')}</span>
          <span>{i18n.t('step2')}</span>
          <span>{i18n.t('step2')}</span>
        </div>
        <div className="sub-desc">
          <p
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:bankAccountVerificationSteps'),
            }}
          />
        </div>
        <dl className="info-list">
          <dt>{i18n.t('accountVerificationTitle')}</dt>
          <dd
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:bankAccountNameMatchRequired'),
            }}
          />
          <dd
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:bankAccountUsageInfo'),
            }}
          />
        </dl>
        <FormProvider {...form}>
          <form onSubmit={handleSubmit(onSubmit)} className="ipt-form-area">
            <TextInput
              label={i18n.t('accountNumber')}
              inputMode="numeric"
              {...register('bankAccount', formOptions.BANK_ACCOUNT)}
              isErrorPaddingPresent={false}
            />
            <TextInput
              label={i18n.t('bank')}
              readOnly
              {...register('bankCode', formOptions.BANK_CDOE)}
              labelClassStr={`bank-logo  + ${appConfig.BANK_CODE}`}
              displayLabel={appConfig.SHORT_BANK_NAME}
              isErrorPaddingPresent={true}
              isShowError={false}
            />
          </form>
        </FormProvider>
      </div>
      <div className="btm-btn-area btn-bottom">
        <button
          type="submit"
          className={clsx('btm-btn app', { disabled: isDisabled })}
          disabled={isDisabled}
          onClick={handleSubmit(onSubmit)}
        >
          {i18n.t('verifyAccount')}
        </button>
      </div>
    </Fragment>
  );
};
